<script lang="ts">
 import{onDestroy}from'svelte';
 import ProfileValueEditor from'./ProfileValueEditor.svelte';
 import{gatewayRequest}from'./gateway';
 import{desktopPreviewSources,desktopPreviewFrames,desktopPreviewResult,desktopPreviewEventLabel,desktopPreviewHeldLabel,previewSourceKey,previewScalar,previewPressed,type DesktopPreviewResult}from'./profile-desktop-preview';
 import type{CompiledSource,CompilationSummary,ProfileCompilerClient}from'./profile-compilation';
 import type{DeepReadonly,ProfileValue}from'./profiles';
 let{preview,compiler,current}:{preview:DeepReadonly<CompilationSummary>;compiler:Pick<ProfileCompilerClient,'inspect'>;current:boolean}=$props();
 let sources=$state.raw<CompiledSource[]>([]),selected=$state(''),pressed=$state<Exclude<ProfileValue,null>>(true),loaded=$state(false),busy=$state(''),error=$state(''),recording=$state.raw<DesktopPreviewResult|null>(null),epoch=0;
 const source=$derived(sources.find(source=>previewSourceKey(source.endpoint)===selected)),schema=$derived(source?previewScalar(source):null);
 $effect(()=>{preview.compilationId;epoch++;sources=[];selected='';loaded=false;recording=null;error='';busy='';});
 onDestroy(()=>{epoch++;});
 async function load(){const pending=++epoch;busy='sources';error='';try{const captured=await desktopPreviewSources(compiler,preview);if(pending===epoch){sources=captured;loaded=true;const first=captured.find(source=>previewScalar(source));selected=first?previewSourceKey(first.endpoint):'';if(first)pressed=previewPressed(first);}}catch(reason){if(pending===epoch)error=reason instanceof Error?reason.message:String(reason);}finally{if(pending===epoch)busy='';}}
 function choose(value:string){selected=value;const source=sources.find(source=>previewSourceKey(source.endpoint)===value);if(source)pressed=previewPressed(source);recording=null;}
 async function record(){if(!current||!loaded)return;const pending=++epoch;busy='recording';error='';recording=null;try{const input=desktopPreviewFrames(sources,selected,pressed),captured=preview;const result=await gatewayRequest({command:'profile_desktop_preview',compilationId:captured.compilationId,...input});const value=desktopPreviewResult(result.profileDesktopPreview,captured);if(pending===epoch)recording=value;}catch(reason){if(pending===epoch)error=reason instanceof Error?reason.message:String(reason);}finally{if(pending===epoch)busy='';}}
</script>
<section class="desktop-preview" aria-label="Keyboard and mouse recording preview">
 <h4>Record keyboard and mouse behavior</h4><p>Synthetic input only. Recording never submits native input, changes enablement or applies a profile. Complete neutral baselines are followed by one selected press, one release and explicit clock ticks through 1.2 seconds.</p>
 <button class="secondary-button" disabled={!!busy||!current} onclick={load}>{busy==='sources'?'Reading captured sources…':'Load captured source controls'}</button>
 {#if loaded}{#if sources.length}<label>Exact recorded source<select aria-label="Exact recorded source" value={selected} disabled={!!busy} onchange={event=>choose(event.currentTarget.value)}>{#each sources.filter(source=>previewScalar(source))as source(previewSourceKey(source.endpoint))}<option value={previewSourceKey(source.endpoint)}>{source.endpoint.nodeId} / {source.endpoint.portId}</option>{/each}</select></label>{#if schema}<ProfileValueEditor {schema} value={pressed} label="Synthetic pressed value" change={value=>{if(value!==null){pressed=value;recording=null;}}}/>{/if}{:else}<p>This captured graph has no external source ports. Record its declared constants and clock behavior.</p>{/if}<button class="primary-button" disabled={!!busy||!current||sources.length>0&&!schema} onclick={record}>{busy==='recording'?'Recording captured program…':'Record without submitting input'}</button>{/if}
 {#if !current}<p role="status">The draft or inventory changed. Refresh native preflight before recording.</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}
 {#if recording}<p role="status"><strong>No native submission</strong> · {recording.operations.length} ordered operations · {recording.operations.filter(operation=>operation.collision).length} ownership collisions</p><p>{recording.limitations}</p>{#if recording.fault}<p class="error" role="alert">{recording.fault}</p>{/if}<div class="recording-table"><table><thead><tr><th>Sequence / operation</th><th>Time (µs)</th><th>Action / owner collision</th><th>Recorded events / held controls</th></tr></thead><tbody>{#each recording.operations as operation,index(index)}<tr><td>{operation.sequence} / {operation.operationId}</td><td>{operation.atUs}</td><td>{operation.actionId}{#if operation.collision}<strong> · shared hold collision</strong>{/if}</td><td>{#each operation.events as event,eventIndex(eventIndex)}<div>{desktopPreviewEventLabel(event)}</div>{:else}<span>No recorded events</span>{/each}<small>Held: {desktopPreviewHeldLabel(operation.held)}</small></td></tr>{:else}<tr><td colspan="4">No desktop operations were produced by this synthetic capture.</td></tr>{/each}</tbody></table></div><details><summary>Timer and ownership decisions · {recording.decisions.length}</summary><pre>{JSON.stringify(recording.decisions,null,2)}</pre></details><details><summary>Deterministic replay trace</summary><pre>{JSON.stringify(recording.trace,null,2)}</pre></details>{/if}
</section>
<style>
 .desktop-preview{border-top:1px solid var(--line);margin-top:18px;padding-top:16px;min-width:0}h4{font-size:12px}p{font-size:10px;line-height:1.8;color:var(--muted)}label{display:grid;gap:6px;font-size:10px;margin:12px 0}select{background:var(--input-bg);color:var(--text);border:1px solid var(--line);border-radius:5px;padding:8px;font-size:10px;max-width:100%}button{font-size:10px;margin:7px 7px 7px 0}.recording-table{overflow:auto;max-height:400px}table{border-collapse:collapse;font-size:10px;width:100%;text-align:left}th,td{padding:9px;border-bottom:1px solid var(--line);vertical-align:top}td small{display:block;margin-top:6px;color:var(--muted)}details{font-size:10px;margin:14px 0}pre{overflow:auto;max-height:300px;font-size:10px}.error{color:#d3a078}
</style>
